module min_slanted_distance (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    // Rectangle 0 (outer)\n    input wire [7:0] h0_0, h1_0,\n    input wire signed [7:0] x0_min, x0_max, y0_min, y0_max,\n    // Rectangle 1 (inner)\n    input wire [7:0] h0_1, h1_1,\n    input wire signed [7:0] x1_min, x1_max, y1_min, y1_max,\n    input wire use_rect1,\n    output reg [15:0] result,\n    output reg done\n);\n\n// State machine definitions\nlocalparam [3:0] IDLE      = 4'd0;\nlocalparam [3:0] CALC_IN   = 4'd1;\nlocalparam [3:0] CALC_DIST0 = 4'd2;\nlocalparam [3:0] CALC_DIST1 = 4'd3;\nlocalparam [3:0] SQRT0     = 4'd4;\nlocalparam [3:0] SQRT1     = 4'd5;\nlocalparam [3:0] COMPARE   = 4'd6;\nlocalparam [3:0] FINISH    = 4'd7;\n\nreg [3:0] state;\n\n// Inside flags\nreg inside0, inside1;\n\n// Distance squared registers\nreg [15:0] dist_sq0, dist_sq1;\nreg [15:0] height_sq0, height_sq1;\nreg [15:0] sum0, sum1;\nreg [31:0] sqrt_input;\nreg [15:0] sqrt_result;\nreg sqrt_valid;\nreg [7:0] counter;\n\n// Candidate values\nreg [15:0] cand_A, cand_B, cand_C;\nreg [15:0] min_val;\n\n// Inside detection function\nfunction [0:0] is_inside;\n    input signed [7:0] x_min, x_max, y_min, y_max;\n    begin\n        is_inside = ($signed(8'd0) >= x_min) && ($signed(8'd0) <= x_max)\n                  && ($signed(8'd0) >= y_min) && ($signed(8'd0) <= y_max);\n    end\nendfunction\n\n// Distance calculation function\nfunction [15:0] calc_dist_sq;\n    input signed [7:0] x_min, x_max, y_min, y_max;\n    reg signed [7:0] dx, dy;\n    reg [15:0] dx_sq, dy_sq;\n    begin\n        if (is_inside(x_min, x_max, y_min, y_max)) begin\n            calc_dist_sq = 16'd0;\n        end else begin\n            dx = ($signed(8'd0) < x_min) ? (x_min - 8'd0) : (($signed(8'd0) > x_max) ? (\n                $signed(8'd0) - x_max) : 8'd0);\n            dy = ($signed(8'd0) < y_min) ? (y_min - 8'd0) : (($signed(8'd0) > y_max) ? (\n                $signed(8'd0) - y_max) : 8'd0);\n            dx_sq = dx * dx;\n            dy_sq = dy * dy;\n            calc_dist_sq = dx_sq + dy_sq;\n        end\n    end\nendfunction\n\n// Square root calculation (restoring algorithm)\nreg [15:0] sqrt_res;\nreg [31:0] sqrt_val;\nreg [4:0] sqrt_bit;\n\ntask sqrt;\n    input [31:0] value;\n    output [15:0] result;\n    reg [31:0] num;\n    reg [15:0] root;\n    reg [16:0] test;\n    integer i;\n    begin\n        num = value;\n        root = 16'd0;\n        test = 17'd0;\n        \n        for (i = 15; i >= 0; i = i - 1) begin\n            test = {root[14:0], 2'b01};\n            if (test << (2*i) <= num) begin\n                root[i] = 1'b1;\n                num = num - (test << (2*i));\n            end\n        end\n        result = root;\n    end\nendtask\n\n// Main state machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        inside0 <= 1'b0;\n        inside1 <= 1'b0;\n        dist_sq0 <= 16'd0;\n        dist_sq1 <= 16'd0;\n        height_sq0 <= 16'd0;\n        height_sq1 <= 16'd0;\n        sum0 <= 16'd0;\n        sum1 <= 16'd0;\n        sqrt_result <= 16'd0;\n        sqrt_valid <= 1'b0;\n        cand_A <= 16'hFFFF;\n        cand_B <= 16'hFFFF;\n        cand_C <= 16'hFFFF;\n        min_val <= 16'hFFFF;\n        result <= 16'd0;\n        done <= 1'b0;\n        counter <= 8'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= CALC_IN;\n                    cand_A <= 16'd0;\n                    cand_B <= 16'd0;\n                    cand_C <= 16'd0;\n                    counter <= 8'd0;\n                end\n            end\n            \n            CALC_IN: begin\n                inside0 <= is_inside(x0_min, x0_max, y0_min, y0_max);\n                inside1 <= use_rect1 && is_inside(x1_min, x1_max, y1_min, y1_max);\n                cand_C <= ({8'd0, (use_rect1 ? h1_1 : h1_0)}) * 16'd256;\n                state <= CALC_DIST0;\n            end\n            \n            CALC_DIST0: begin\n                if (!inside0) begin\n                    dist_sq0 <= calc_dist_sq(x0_min, x0_max, y0_min, y0_max);\n                    height_sq0 <= h0_0 * h0_0;\n                end\n                state <= inside0 ? (use_rect1 ? CALC_DIST1 : COMPARE) : SQRT0;\n            end\n            \n            CALC_DIST1: begin\n                if (inside0 && !inside1 && use_rect1) begin\n                    dist_sq1 <= calc_dist_sq(x1_min, x1_max, y1_min, y1_max);\n                    height_sq1 <= h0_1 * h0_1;\n                end\n                state <= SQRT1;\n            end\n            \n            SQRT0: begin\n                sqrt_input <= {sum0, 16'd0};\n                sqrt(dist_sq0 + height_sq0, sqrt_result);\n                sqrt_valid <= 1'b1;\n                state <= (use_rect1 && inside0) ? CALC_DIST1 : COMPARE;\n            end\n            \n            SQRT1: begin\n                sqrt_input <= {sum1, 16'd0};\n                sqrt(dist_sq1 + height_sq1, sqrt_result);\n                sqrt_valid <= 1'b1;\n                state <= COMPARE;\n            end\n            \n            COMPARE: begin\n                sqrt_valid <= 1'b0;\n                if (!inside0) cand_A <= sqrt_result;\n                if (inside0 && use_rect1 && !inside1) cand_B <= sqrt_result;\n                \n                min_val <= cand_C;\n                if (cand_A < min_val) min_val <= cand_A;\n                if (cand_B < min_val) min_val <= cand_B;\n                \n                state <= FINISH;\n            end\n            \n            FINISH: begin\n                result <= min_val;\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule